import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from 'lib/lemon-ui/LemonToast/LemonToast'
import { getCurrentTeamId } from 'lib/utils/getAppContext'

import { conversationsMySignatureCreate, conversationsMySignatureRetrieve } from '../../generated/api'
import type { AgentSignatureApi } from '../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentSignatureLogicValues {
    draftIncludeProfilePicture: boolean
    draftText: string
    hasChanges: boolean
    signature: AgentSignatureApi | null
    signatureLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentSignatureLogicActions {
    loadSignature: () => any
    loadSignatureFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadSignatureSuccess: (
        signature: AgentSignatureApi,
        payload?: any
    ) => {
        signature: AgentSignatureApi
        payload?: any
    }
    saveSignature: () => any
    saveSignatureFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    saveSignatureSuccess: (
        signature: AgentSignatureApi,
        payload?: any
    ) => {
        signature: AgentSignatureApi
        payload?: any
    }
    setDraftIncludeProfilePicture: (include: boolean) => {
        include: boolean
    }
    setDraftText: (text: string) => {
        text: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface agentSignatureLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        hasChanges: (signature: any, draftText: any, draftIncludeProfilePicture: any) => boolean
    }
}

export type agentSignatureLogicType = MakeLogicType<
    agentSignatureLogicValues,
    agentSignatureLogicActions,
    Record<string, any>,
    agentSignatureLogicMeta
>

export const agentSignatureLogic = kea<agentSignatureLogicType>([
    path(['products', 'conversations', 'frontend', 'scenes', 'settings', 'agentSignatureLogic']),
    actions({
        setDraftText: (text: string) => ({ text }),
        setDraftIncludeProfilePicture: (include: boolean) => ({ include }),
    }),
    loaders(({ values }) => ({
        signature: [
            null as AgentSignatureApi | null,
            {
                loadSignature: async () => await conversationsMySignatureRetrieve(String(getCurrentTeamId())),
                saveSignature: async () =>
                    await conversationsMySignatureCreate(String(getCurrentTeamId()), {
                        text: values.draftText,
                        include_profile_picture: values.draftIncludeProfilePicture,
                    }),
            },
        ],
    })),
    reducers({
        draftText: [
            '',
            {
                setDraftText: (_, { text }) => text,
                loadSignatureSuccess: (_, { signature }) => signature?.text ?? '',
                saveSignatureSuccess: (_, { signature }) => signature?.text ?? '',
            },
        ],
        draftIncludeProfilePicture: [
            true,
            {
                setDraftIncludeProfilePicture: (_, { include }) => include,
                loadSignatureSuccess: (_, { signature }) => signature?.include_profile_picture ?? true,
                saveSignatureSuccess: (_, { signature }) => signature?.include_profile_picture ?? true,
            },
        ],
    }),
    selectors({
        hasChanges: [
            (s) => [s.signature, s.draftText, s.draftIncludeProfilePicture],
            (signature: AgentSignatureApi | null, draftText: string, draftIncludeProfilePicture: boolean): boolean =>
                signature !== null &&
                (signature.text !== draftText.trim() ||
                    signature.include_profile_picture !== draftIncludeProfilePicture),
        ],
    }),
    listeners({
        saveSignatureSuccess: () => {
            lemonToast.success('Signature saved')
        },
        saveSignatureFailure: () => {
            lemonToast.error('Could not save your signature. Try again.')
        },
    }),
    afterMount(({ actions }) => {
        actions.loadSignature()
    }),
])
